  if (!Array.isArray(arr2) || arr2.length < 1 || arr2.length > 50000) return 'arr2 needs 1 to 5 * 10^4 values.';
  if ([...arr1, ...arr2].some(v => !Number.isInteger(v) || v < 1 || v > 100000000)) return 'Every value is an integer from 1 to 10^8.';
