function longestCommonPrefix(arr1, arr2) {
  const prefixes = new Set();
  for (const num of arr1) {
    let value = num;
    while (value > 0) {
      prefixes.add(value);
      value = Math.floor(value / 10);
    }
  }

  let best = 0;
  for (const num of arr2) {
    let value = num;
    while (value > 0 && !prefixes.has(value)) {
      value = Math.floor(value / 10);
    }
    if (value > 0) {
      best = Math.max(best, String(value).length);
    }
  }
  return best;
}

