function generate(rand, size) {
  const large = size === 'large';
  const digit = () => String(Math.floor(rand() * (large ? 10 : 3)));
  const rootCount = large ? 40 : 2;
  const roots = Array.from({ length: rootCount }, () => {
    let s = String(1 + Math.floor(rand() * 9));
    while (s.length < 8) s += digit();
    return s;
  });
  const maxLen = large ? 4 + Math.floor(rand() * 5) : 8;
  const make = pool => {
    if (!large && rand() < 0.05) return 100000000;
    const root = pool[Math.floor(rand() * pool.length)];
    const len = 1 + Math.floor(rand() * maxLen);
    let s = root.slice(0, 1 + Math.floor(rand() * len));
    while (s.length < len) s += digit();
    return Number(s);
  };
  let pool1 = roots, pool2 = roots;
  // Sometimes draw the two arrays from roots with different first digits, so no pair shares a prefix.
  if (!large && rand() < 0.25 && roots[0][0] !== roots[1][0]) {
    pool1 = [roots[0]];
    pool2 = [roots[1]];
    const fresh = pool => () => { const s = make(pool); return s === 100000000 && pool[0][0] !== '1' ? Number(pool[0][0]) : s; };
    const n1 = 1 + Math.floor(rand() * 6), n2 = 1 + Math.floor(rand() * 6);
    const a1 = Array.from({ length: n1 }, fresh(pool1));
    const a2 = Array.from({ length: n2 }, fresh(pool2));
    if (a1.some(v => String(v)[0] === roots[1][0]) || a2.some(v => String(v)[0] === roots[0][0])) return [a1, a1.slice()];
    return [a1, a2];
  }
  const n1 = large ? 2000 : 1 + Math.floor(rand() * 6);
  const n2 = large ? 2000 : 1 + Math.floor(rand() * 6);
  return [Array.from({ length: n1 }, () => make(pool1)), Array.from({ length: n2 }, () => make(pool2))];
}
